SELECT

FROM TODAY_HISTORY_LINK
WHERE
LOGIC_DEL = 0

    AND PAGE_ID = #{dto.pageId}


    AND ITEM_ID = #{dto.itemId}


    AND HISTORY_KEY = #{dto.historyKey}


    AND LINK_TEXT = #{dto.linkText}


    AND LINK_URL = #{dto.linkUrl}


    AND LINK_TITLE = #{dto.linkTitle}


    AND INTERNAL_FLAG = #{dto.internalFlag}


    AND SORT_NO = #{dto.sortNo}


    AND LINK_HASH = #{dto.linkHash}

ORDER BY create_time DESC

SELECT

FROM TODAY_HISTORY_LINK
WHERE LOGIC_DEL = 0

    AND ID = #{dto.id}}


    AND PAGE_ID = #{dto.pageId}


    AND ITEM_ID = #{dto.itemId}


    AND HISTORY_KEY = #{dto.historyKey}


    AND LINK_TEXT = #{dto.linkText}


    AND LINK_URL = #{dto.linkUrl}


    AND LINK_TITLE = #{dto.linkTitle}


    AND INTERNAL_FLAG = #{dto.internalFlag}


    AND SORT_NO = #{dto.sortNo}


    AND LINK_HASH = #{dto.linkHash}

ORDER BY MODIFY_TIME DESC

SELECT

FROM TODAY_HISTORY_LINK
WHERE LOGIC_DEL = 0

    AND ID = #{dto.id}}


    AND PAGE_ID = #{dto.pageId}


    AND ITEM_ID = #{dto.itemId}


    AND HISTORY_KEY = #{dto.historyKey}


    AND LINK_TEXT = #{dto.linkText}


